// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlusJakartaSans = makeLoadFont('PlusJakartaSans');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: titleFontFamily } = loadPlusJakartaSans();
const { fontFamily: bodyFontFamily } = loadSpaceGrotesk();

// Helper to calculate star vertices centered at (cx, cy)
const getStarVertices = (cx: number, cy: number, R: number, r: number) => {
  const vertices = [];
  for (let i = 0; i < 10; i++) {
    const angle = -Math.PI / 2 + (i * Math.PI) / 5;
    const radius = i % 2 === 0 ? R : r;
    vertices.push({
      x: cx + radius * Math.cos(angle),
      y: cy + radius * Math.sin(angle),
    });
  }
  return vertices;
};

// Facet definitions to map the 3D look
const facets = [
  { p1: 0, p2: 1, type: "dark" },
  { p1: 1, p2: 2, type: "light" },
  { p1: 2, p2: 3, type: "dark" },
  { p1: 3, p2: 4, type: "light" },
  { p1: 4, p2: 5, type: "dark" },
  { p1: 5, p2: 6, type: "dark" }, // Bottom-left arm right side (shading matches reference)
  { p1: 6, p2: 7, type: "light" },
  { p1: 7, p2: 8, type: "dark" },
  { p1: 8, p2: 9, type: "light" },
  { p1: 9, p2: 0, type: "light" },
];



export type StarRatingProps = Record<string, any>;

// Separate Star component to cleanly encapsulate springs & performance
const Star: React.FC<{
  index: number;
  frame: number;
  fps: number;
  s: number;
  activeLight: string;
  activeDark: string;
}> = ({ index, frame, fps, s, activeLight, activeDark }) => {
  const triggerFrame = 15 + index * 12;

  // Premium, luxury inactive dark-star colors to match reference
  const inactiveLight = "#17243a";
  const inactiveDark = "#0f1a2b";

  const starSpring = spring({
    frame: frame - triggerFrame,
    fps,
    config: {
      damping: 11,
      mass: 0.5,
      stiffness: 110,
    },
  });

  // activeScale controls the overlay gold-fill scaling
  const activeScale = interpolate(starSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // containerScale adds a physical juice pop effect to the entire star container
  const containerScale = interpolate(starSpring, [0, 0.4, 1], [1, 1.15, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const R = 60 * s;
  const r = R * 0.382;
  const cx = R;
  const cy = R;

  const vertices = getStarVertices(cx, cy, R, r);

  return (
    <div
      style={{
        width: R * 2,
        height: R * 2,
        position: "relative",
        transform: `scale(${containerScale})`,
        transition: "none",
      }}
    >
      {/* Base empty star (always visible) */}
      <svg
        width={R * 2}
        height={R * 2}
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          overflow: "visible",
          transition: "none",
        }}
      >
        {facets.map((f, idx) => {
          const p1 = vertices[f.p1];
          const p2 = vertices[f.p2];
          const points = `${cx},${cy} ${p1.x},${p1.y} ${p2.x},${p2.y}`;
          const fill = f.type === "light" ? inactiveLight : inactiveDark;
          return (
            <polygon
              key={idx}
              points={points}
              fill={fill}
              style={{ transition: "none" }}
            />
          );
        })}
      </svg>

      {/* Active gold star overlay */}
      <svg
        width={R * 2}
        height={R * 2}
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          overflow: "visible",
          transform: `scale(${activeScale})`,
          transformOrigin: "center",
          opacity: activeScale > 0 ? 1 : 0,
          transition: "none",
        }}
      >
        {facets.map((f, idx) => {
          const p1 = vertices[f.p1];
          const p2 = vertices[f.p2];
          const points = `${cx},${cy} ${p1.x},${p1.y} ${p2.x},${p2.y}`;
          const fill = f.type === "light" ? activeLight : activeDark;
          return (
            <polygon
              key={idx}
              points={points}
              fill={fill}
              style={{ transition: "none" }}
            />
          );
        })}
      </svg>
    </div>
  );
};

export const StarRating: React.FC<StarRatingProps> = ({
  backgroundColor = "#030914",
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "CUSTOMER SATISFACTION",
  titleFontSize = 26,
  subText = "based on 12,500+ global reviews",
  subTextFontSize = 20,
  ratingLabel = "EXCELLENT",
  ratingLabelFontSize = 22,
  ratingValueFontSize = 84,
  starActiveColorLight = "#ffd000",
  starActiveColorDark = "#ff9f00",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive scale factor (all sizes, spacings, and paddings trace back to this)
  const s = Math.min(width, height) / 1080;

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Rating counting animation from 0.0 to 5.0
  const ratingValue = interpolate(
    frame,
    [15, 22, 27, 34, 39, 46, 51, 58, 63, 70],
    [0.0, 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0, 5.0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const displayedRating = ratingValue.toFixed(1);

  // Layout entrances
  const headerOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const headerY = interpolate(frame, [0, 15], [-20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  const ratingOpacity = interpolate(frame, [5, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const ratingScale = interpolate(frame, [5, 20], [0.95, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  // "EXCELLENT" badge entry trigger (triggered slightly after 5th star sparks begin)
  const badgeSpring = spring({ frame: frame - 69, fps });
  const badgeOpacity = interpolate(badgeSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const badgeY = interpolate(badgeSpring, [0, 1], [15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const badgeScale = interpolate(badgeSpring, [0, 1], [0.8, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Sparks Burst System (Fifth Star impact happens around frame 69)
  const sparkImpactFrame = 69;
  const sparkCount = 28;

  const sparkData = useMemo(() => {
    const list = [];
    for (let i = 0; i < sparkCount; i++) {
      // Deterministic angle distribution with slight natural variations
      const angle = (i * 2 * Math.PI) / sparkCount + Math.sin(i * 12.3) * 0.1;
      
      // Rotate through different visual types: 0 = comet lines, 1 = 4-point stars, 2 = tiny dots
      let type = 0;
      if (i % 4 === 1) type = 1;
      else if (i % 4 === 3) type = 2;

      const speedFactor = 0.85 + Math.abs(Math.sin(i * 45.6)) * 0.6;
      const length = 25 + Math.abs(Math.sin(i * 78.9)) * 35;
      const size = 12 + Math.abs(Math.sin(i * 32.1)) * 14;
      
      // Palette mapping: Yellow Gold, Soft Warm White, Pure White
      const color = i % 2 === 0 ? "#ffd000" : i % 3 === 0 ? "#fffae0" : "#ffffff";
      const delay = Math.abs(Math.sin(i * 9.5)) * 4; // slight timing offsets for natural spread

      list.push({ angle, type, length, size, color, delay, speedFactor });
    }
    return list;
  }, []);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Background radial atmosphere */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width,
          height,
          background: `radial-gradient(circle at 50% 50%, #152542 0%, #030914 80%)`,
          opacity: 0.65,
          pointerEvents: "none",
        }}
      />

      {/* Top Header Label */}
      <div
        style={{
          position: "absolute",
          top: 180 * s,
          left: 0,
          right: 0,
          textAlign: "center",
          fontFamily: titleFontFamily,
          color: "#ffffff",
          fontSize: titleFontSize * s,
          fontWeight: 800,
          letterSpacing: `${5 * s}px`,
          opacity: headerOpacity,
          transform: `translateY(${headerY * s}px)`,
          transition: "none",
        }}
      >
        {titleText}
      </div>

      {/* Main Stars Container Row */}
      <div
        style={{
          position: "absolute",
          top: "43%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap: 32 * s,
          transition: "none",
        }}
      >
        {[0, 1, 2, 3, 4].map((i) => (
          <Star
            key={i}
            index={i}
            frame={frame}
            fps={fps}
            s={s}
            activeLight={starActiveColorLight}
            activeDark={starActiveColorDark}
          />
        ))}

        {/* Absolute Sparks Overlay relative to the 5th Star center */}
        {/* Math verify: 5 stars spaced 32s with size 120s means center of 5th star is exactly 304s from center */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: `translate(calc(-50% + ${304 * s}px), -50%)`,
            width: 0,
            height: 0,
            pointerEvents: "none",
            overflow: "visible",
            transition: "none",
          }}
        >
          {sparkData.map((spark, idx) => {
            const localFrame = frame - sparkImpactFrame - spark.delay;
            
            // Fully invisible and unmounted before its specific animation frame
            if (localFrame < 0) return null;

            const duration = 24;
            const progress = Math.min(Math.max(localFrame / duration, 0), 1);
            
            // Unmount if particle finishes its lifespan
            if (progress >= 1) return null;

            const eased = Easing.out(Easing.quad)(progress);
            const startRadius = 55 * s;
            const maxSpread = (170 + spark.speedFactor * 130) * s;
            const currentRadius = startRadius + (maxSpread - startRadius) * eased;

            // Fade & scale over life
            const opacity = interpolate(progress, [0, 0.12, 0.55, 1], [0, 1, 1, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            const scale = interpolate(progress, [0, 0.15, 0.75, 1], [0, 1, 1, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

            const cx = currentRadius * Math.cos(spark.angle);
            const cy = currentRadius * Math.sin(spark.angle);

            if (spark.type === 2) {
              // Particle Type 2: Dot
              return (
                <div
                  key={idx}
                  style={{
                    position: "absolute",
                    left: cx,
                    top: cy,
                    width: spark.size * s * scale,
                    height: spark.size * s * scale,
                    borderRadius: "50%",
                    backgroundColor: spark.color,
                    opacity,
                    transform: "translate(-50%, -50%)",
                    transition: "none",
                  }}
                />
              );
            }

            if (spark.type === 1) {
              // Particle Type 1: Pinched 4-point Spark Star
              const size = spark.size * s * scale;
              const half = size / 2;
              const pathD = `M 0,${-half} Q 0,0 ${half},0 Q 0,0 0,${half} Q 0,0 ${-half},0 Q 0,0 0,${-half} Z`;
              const rotation = (spark.angle * 180) / Math.PI + progress * 90; // slight spin

              return (
                <svg
                  key={idx}
                  width={size}
                  height={size}
                  style={{
                    position: "absolute",
                    left: cx - half,
                    top: cy - half,
                    opacity,
                    transform: `rotate(${rotation}deg)`,
                    overflow: "visible",
                    transition: "none",
                  }}
                >
                  <path d={pathD} fill={spark.color} style={{ transition: "none" }} />
                </svg>
              );
            }

            // Particle Type 0: Comet / Shooting Line Segment
            // Line endpoint stretches and shoots outward dynamically
            const segmentStartProgress = interpolate(progress, [0, 0.7], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            const segmentEndProgress = interpolate(progress, [0.15, 1], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

            const startRadiusScaled = startRadius + (maxSpread - startRadius) * Easing.out(Easing.quad)(segmentStartProgress);
            const endRadiusScaled = (startRadius + spark.length * s) + (maxSpread - startRadius) * Easing.out(Easing.quad)(segmentEndProgress);

            const x1 = startRadiusScaled * Math.cos(spark.angle);
            const y1 = startRadiusScaled * Math.sin(spark.angle);
            const x2 = endRadiusScaled * Math.cos(spark.angle);
            const y2 = endRadiusScaled * Math.sin(spark.angle);

            return (
              <svg
                key={idx}
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  width: 1,
                  height: 1,
                  overflow: "visible",
                  opacity,
                  transition: "none",
                }}
              >
                <line
                  x1={x1}
                  y1={y1}
                  x2={x2}
                  y2={y2}
                  stroke={spark.color}
                  strokeWidth={3.5 * s}
                  strokeLinecap="round"
                  style={{ transition: "none" }}
                />
              </svg>
            );
          })}
        </div>
      </div>

      {/* Bottom Rating Display Stack */}
      <div
        style={{
          position: "absolute",
          bottom: 160 * s,
          left: 0,
          right: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 12 * s,
          transition: "none",
        }}
      >
        {/* Large Counter Score */}
        <div
          style={{
            fontFamily: titleFontFamily,
            fontSize: ratingValueFontSize * s,
            fontWeight: 800,
            color: "#ffffff",
            opacity: ratingOpacity,
            transform: `scale(${ratingScale})`,
            transition: "none",
            letterSpacing: "-1px",
          }}
        >
          {displayedRating}
        </div>

        {/* Explanatory Review Subtext */}
        <div
          style={{
            fontFamily: bodyFontFamily,
            fontSize: subTextFontSize * s,
            fontWeight: 500,
            color: "#8fa0bc",
            opacity: ratingOpacity,
            letterSpacing: `${1 * s}px`,
            transition: "none",
          }}
        >
          {subText}
        </div>

        {/* Elegant "EXCELLENT" Badge */}
        <div
          style={{
            fontFamily: titleFontFamily,
            fontSize: ratingLabelFontSize * s,
            fontWeight: 800,
            backgroundColor: `${starActiveColorLight}12`,
            border: `${1.5 * s}px solid ${starActiveColorLight}30`,
            color: starActiveColorLight,
            padding: `${10 * s}px ${28 * s}px`,
            borderRadius: 50 * s,
            marginTop: 18 * s,
            letterSpacing: `${3 * s}px`,
            opacity: badgeOpacity,
            transform: `translateY(${badgeY * s}px) scale(${badgeScale})`,
            boxShadow: `0 ${8 * s}px ${24 * s}px rgba(0,0,0,0.25)`,
            transition: "none",
          }}
        >
          {ratingLabel}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default StarRating;